package com.classvoice.controller; import com.classvoice.dao.*; import com.classvoice.model.User; import jakarta.servlet.annotation.WebServlet; import jakarta.servlet.http.*; import jakarta.servlet.*; import java.io.IOException;
@WebServlet("/teacher/dashboard") public class TeacherDashboardServlet extends HttpServlet {protected void doGet(HttpServletRequest r,HttpServletResponse p)throws ServletException,IOException{try{User u=(User)r.getSession().getAttribute("user");LectureDAO l=new LectureDAO();r.setAttribute("lectures",l.findByTeacher(u.getUserId()));r.setAttribute("activeCount",l.countActive(u.getUserId()));r.setAttribute("feedbackCount",l.countFeedback(u.getUserId()));r.getRequestDispatcher("/WEB-INF/views/teacher-dashboard.jsp").forward(r,p);}catch(Exception e){throw new ServletException(e);}}}
